  Object.entries(data.value?.焦点人物 ?? {}).map(([name, item]) => ({ name, ...item })),
);

const topFocusCharacters = computed(() => focusCharacters.value.slice(0, 4));

function openCharacter(name: string) {
  selectedCharacter.value = focusCharacters.value.find(item => item.name === name) ?? null;
}
